// Generated Official Survey of India (SOI) Vector Map Geometry
// Includes Jammu & Kashmir and Ladakh in their entirety (including PoK and Aksai Chin)

export interface StateMapFeature {
  id: string;
  name: string;
  d: string;
  level: 'critical' | 'high' | 'medium' | 'low';
  hazard: string;
  alerts: number;
  centroid: [number, number];
  lat: number;
  lng: number;
}

export const INDIA_MAP_VIEWBOX = '10 8 585 660';

export const MIN_LNG = 67.5;
export const MAX_LNG = 97.8;
export const MIN_LAT = 5.2;
export const MAX_LAT = 37.6;
export const MAP_WIDTH = 600;
export const MAP_HEIGHT = 680;

export function projectCoordinates(lng: number, lat: number): [number, number] {
  const x = ((lng - MIN_LNG) / (MAX_LNG - MIN_LNG)) * MAP_WIDTH;
  const latRad = (lat * Math.PI) / 180;
  const yMerc = Math.log(Math.tan(Math.PI / 4 + latRad / 2));
  const minLatRad = (MIN_LAT * Math.PI) / 180;
  const maxLatRad = (MAX_LAT * Math.PI) / 180;
  const yMinMerc = Math.log(Math.tan(Math.PI / 4 + minLatRad / 2));
  const yMaxMerc = Math.log(Math.tan(Math.PI / 4 + maxLatRad / 2));
  const y = MAP_HEIGHT - (((yMerc - yMinMerc) / (yMaxMerc - yMinMerc)) * MAP_HEIGHT);
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

